function [SignalOut, P] = QAM_Generator(P, Sequence)
% Generates arbitrary square QAM.
%
% Sequence is either a 1xN binary sequence (which is used multiple
% times with equal decorrelation) or a Np*log2(M)xN matrix of binary
% sequences which are mapped to the Np*log2(M) bits of this signal.
%
% P.M Number of constellation points
%
% N.B. For convenience, actual operation always generates for Np=2, then discards one
% polarisation
%
% Author: Domanic Lavery, December 2013
%
% If size(Sequence,1) > 1, Sequence(1,:) and Sequence(2,:) are asigned for 
% different polarization.
% Modified: Yuta Wakayama, July 2019

str = P.ModFormat;
switch str
    case 'QPSK'
        P.M = 4;
        regularQAM = true;
    case {'4QAM','8QAM','16QAM','64QAM','256QAM','1024QAM'}
        P.M = str2double(str(1:end-3));
        regularQAM = true;
